import java.util.*;

enum Farbe { ROT, GRUEN, BLAU }

enum Planet {
    MERKUR(3.7), ERDE(9.81), MARS(3.71);

    private final double g;

    Planet(double g) { this.g = g; }

    double gewicht(double masse) { return masse * g; }

    boolean istSchwer() { return g > 5; }
}

record Punkt(int x, int y) {
    Punkt {
        if (x < 0) throw new IllegalArgumentException("x < 0");
    }

    double abstand() { return Math.sqrt(x * x + y * y); }

    static Punkt ursprung() { return new Punkt(0, 0); }
}

record Person(String name, int alter) implements Comparable<Person> {
    public int compareTo(Person o) { return Integer.compare(alter, o.alter); }
}

sealed interface Form permits Kreis, Rechteck {}
record Kreis(double r) implements Form {}
record Rechteck(double a, double b) implements Form {}

public class Main {
    static String text(Farbe f) {
        switch (f) {
            case ROT: return "warm";
            case BLAU: return "kalt";
            default: return "neutral";
        }
    }

    static double flaeche(Form f) {
        return switch (f) {
            case Kreis k -> 3 * k.r() * k.r();
            case Rechteck(double a, double b) -> a * b;
        };
    }

    public static void main(String[] args) {
        Farbe f = Farbe.GRUEN;
        System.out.println(f + " " + f.name() + " " + f.ordinal());
        for (Farbe x : Farbe.values()) {
            System.out.println(x + " ist " + text(x));
        }
        System.out.println(Farbe.valueOf("BLAU") == Farbe.BLAU);
        System.out.println(f.compareTo(Farbe.BLAU) + " " + Farbe.values().length);
        String wert = switch (f) {
            case ROT -> "R";
            case GRUEN -> "G";
            case BLAU -> "B";
        };
        System.out.println(wert);
        for (Planet p : Planet.values()) {
            System.out.printf("%s %.1f %b%n", p, p.gewicht(10), p.istSchwer());
        }
        try {
            Farbe.valueOf("LILA");
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
        List<Farbe> liste = new ArrayList<>(List.of(Farbe.BLAU, Farbe.ROT));
        Collections.sort(liste);
        System.out.println(liste);

        Punkt p = new Punkt(3, 4);
        Punkt q = new Punkt(3, 4);
        System.out.println(p + " " + p.x() + " " + p.abstand());
        System.out.println(p.equals(q) + " " + (p == q) + " " + (p.hashCode() == q.hashCode()));
        System.out.println(Punkt.ursprung());
        try {
            new Punkt(-1, 0);
        } catch (IllegalArgumentException e) {
            System.out.println("abgelehnt: " + e.getMessage());
        }
        Set<Punkt> punkte = new HashSet<>();
        punkte.add(p);
        punkte.add(q);
        punkte.add(new Punkt(1, 2));
        System.out.println(punkte.size());
        Map<Punkt, String> namen = new HashMap<>();
        namen.put(new Punkt(1, 1), "eins");
        System.out.println(namen.get(new Punkt(1, 1)));
        List<Person> leute = new ArrayList<>();
        leute.add(new Person("Ada", 36));
        leute.add(new Person("Bob", 20));
        leute.add(new Person("Cy", 28));
        Collections.sort(leute);
        System.out.println(leute);
        System.out.println(flaeche(new Kreis(2)) + " " + flaeche(new Rechteck(2, 5)));
        Object o = new Rechteck(3, 3);
        if (o instanceof Rechteck(double a, double b) && a == b) {
            System.out.println("Quadrat " + a);
        }
        Object[] dinge = {42, "Text", p, Farbe.ROT, 2.5, null};
        for (Object d : dinge) {
            String art = switch (d) {
                case null -> "nichts";
                case Integer i when i > 40 -> "große Zahl " + i;
                case Integer i -> "Zahl " + i;
                case String s -> "Text der Länge " + s.length();
                case Punkt(int x, int y) -> "Punkt bei " + x + "/" + y;
                case Farbe c -> "Farbe " + c.ordinal();
                default -> "etwas anderes: " + d;
            };
            System.out.println(art);
        }
    }
}

class ZuWenigGeldException extends Exception {
    private final double fehlbetrag;
    ZuWenigGeldException(String meldung, double fehlbetrag) {
        super(meldung);
        this.fehlbetrag = fehlbetrag;
    }
    double getFehlbetrag() { return fehlbetrag; }
}

class Fehler extends RuntimeException {
    Fehler(String text, Throwable grund) { super(text, grund); }
}

public class Main {
    static double stand = 50;

    static void abheben(double betrag) throws ZuWenigGeldException {
        if (betrag > stand) {
            throw new ZuWenigGeldException("Nur " + stand + " da", betrag - stand);
        }
        stand -= betrag;
    }

    static int teile(int a, int b) {
        try {
            return a / b;
        } finally {
            System.out.println("finally in teile");
        }
    }

    static int stufe(int n) {
        if (n == 0) throw new IllegalStateException("Boden erreicht");
        return stufe(n - 1) + 1;
    }

    public static void main(String[] args) {
        try {
            abheben(20);
            System.out.println("Stand: " + stand);
            abheben(100);
            System.out.println("nie");
        } catch (ZuWenigGeldException e) {
            System.out.println("Fehler: " + e.getMessage());
            System.out.println("Fehlt: " + e.getFehlbetrag());
            System.out.println(e);
        } finally {
            System.out.println("Ende Abheben");
        }

        System.out.println(teile(7, 2));
        try {
            System.out.println(teile(1, 0));
        } catch (ArithmeticException e) {
            System.out.println("Gefangen: " + e.getMessage());
            System.out.println(e);
        }

        int[] zahlen = {1, 2, 3};
        try {
            zahlen[3] = 4;
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println(e.getMessage());
        }

        String[] eingaben = {"12", "x1", "7"};
        int summe = 0;
        for (String s : eingaben) {
            try {
                summe += Integer.parseInt(s);
            } catch (NumberFormatException e) {
                System.out.println("Keine Zahl: " + e.getMessage());
            }
        }
        System.out.println("Summe: " + summe);

        try {
            "abc".charAt(5);
        } catch (StringIndexOutOfBoundsException | NullPointerException e) {
            System.out.println("Multi: " + e.getClass().getSimpleName());
        }

        try {
            stufe(3);
        } catch (RuntimeException e) {
            System.out.println(e.getClass().getName() + " / " + e.getMessage());
        }

        try {
            try {
                Object o = "Text";
                Integer i = (Integer) o;
            } catch (ClassCastException e) {
                throw new Fehler("Umwandlung kaputt", e);
            }
        } catch (Fehler e) {
            System.out.println(e.getMessage());
            System.out.println(e.getCause() instanceof ClassCastException);
        }

        try {
            throw new UnsupportedOperationException();
        } catch (Exception e) {
            System.out.println(e.getMessage());
            System.out.println(e);
        }

        try {
            throw new IllegalArgumentException("böse");
        } catch (IllegalStateException e) {
            System.out.println("falsch");
        } catch (IllegalArgumentException e) {
            System.out.println("richtig: " + e.getMessage());
        }
        int versuche = 0;
        while (true) {
            try {
                versuche++;
                if (versuche < 3) throw new RuntimeException("nochmal");
                System.out.println("geschafft nach " + versuche);
                break;
            } catch (RuntimeException e) {
                System.out.println(e.getMessage() + " " + versuche);
            }
        }
    }
}

import java.util.*;

public class Main {
    static class Ungueltig extends RuntimeException {
        Ungueltig(String text) { super(text); }
    }

    static int pruefe(int alter) {
        if (alter < 0) throw new Ungueltig("negativ: " + alter);
        return alter;
    }

    static String versuche(String eingabe) {
        try {
            int zahl = Integer.parseInt(eingabe.trim());
            return "ok " + pruefe(zahl);
        } catch (NumberFormatException e) {
            return "keine Zahl";
        } catch (Ungueltig e) {
            return "ungültig (" + e.getMessage() + ")";
        } finally {
            System.out.print("[" + eingabe + "] ");
        }
    }

    static int tief(int n) throws Exception {
        try {
            if (n == 0) throw new Exception("unten");
            return tief(n - 1);
        } finally {
            System.out.print(n);
        }
    }

    public static void main(String[] args) {
        for (String s : new String[] {" 42", "x", "-3"}) {
            System.out.println(versuche(s));
        }
        try {
            tief(3);
        } catch (Exception e) {
            System.out.println(" " + e.getMessage());
        }
        try {
            Object o = null;
            o.toString();
        } catch (NullPointerException e) {
            System.out.println("NPE gefangen");
        }
        try {
            List<Integer> leer = new ArrayList<>();
            System.out.println(leer.get(0));
        } catch (IndexOutOfBoundsException e) {
            System.out.println(e.getClass().getSimpleName() + ": " + e.getMessage());
        }
        try {
            new ArrayDeque<String>().pop();
        } catch (NoSuchElementException e) {
            System.out.println("leer " + (e.getMessage() == null));
        }
        try {
            throw new Ungueltig("eigen");
        } catch (RuntimeException e) {
            System.out.println(e);
        }
        RuntimeException r = new IllegalStateException("Zustand", new ArithmeticException("Grund"));
        System.out.println(r.getMessage() + " <- " + r.getCause().getMessage());
        Exception ohne = new Exception();
        System.out.println(ohne.getMessage() + " " + ohne);
        int[] a = new int[2];
        int index = 5;
        try {
            a[index] = 1;
        } catch (RuntimeException e) {
            System.out.println(e.getMessage());
        } finally {
            index = 0;
        }
        System.out.println(index);
    }
}

