import java.util.*;

abstract class Fahrzeug implements Comparable<Fahrzeug> {
    private static int anzahl;
    protected final String marke;
    protected int tempo;

    protected Fahrzeug(String marke) {
        this.marke = marke;
        anzahl++;
    }

    public static int getAnzahl() { return anzahl; }

    public abstract int maxTempo();

    public void beschleunigen(int delta) {
        tempo = Math.min(tempo + delta, maxTempo());
    }

    @Override
    public int compareTo(Fahrzeug o) {
        return Integer.compare(maxTempo(), o.maxTempo());
    }

    @Override
    public String toString() {
        return String.format("%s(%d/%d)", marke, tempo, maxTempo());
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Fahrzeug f)) return false;
        return marke.equals(f.marke);
    }

    @Override
    public int hashCode() { return marke.hashCode(); }
}

class Auto extends Fahrzeug {
    Auto(String marke) { super(marke); }
    public int maxTempo() { return 180; }
}

final class Rad extends Fahrzeug {
    Rad() { super("Rad"); }
    @Override public int maxTempo() { return 30; }
    @Override public void beschleunigen(int delta) {
        super.beschleunigen(delta / 2);
        System.out.println("strampeln");
    }
}

public class Main {
    public static void main(String[] args) {
        List<Fahrzeug> alle = new ArrayList<>();
        alle.add(new Auto("VW"));
        alle.add(new Rad());
        alle.add(new Auto("BMW"));
        for (Fahrzeug f : alle) f.beschleunigen(100);
        Collections.sort(alle);
        System.out.println(alle);
        System.out.println(Fahrzeug.getAnzahl());
        Set<Fahrzeug> set = new HashSet<>(alle);
        set.add(new Auto("VW"));
        System.out.println(set.size() + " " + alle.contains(new Auto("BMW")) + " " + alle.indexOf(new Rad()));
        Fahrzeug schnellstes = Collections.max(alle);
        System.out.println(schnellstes.marke + " " + Fahrzeug.getAnzahl());
        Map<String, Fahrzeug> nachMarke = new HashMap<>();
        for (Fahrzeug f : alle) nachMarke.put(f.marke, f);
        System.out.println(nachMarke.keySet());
        Object o = alle.get(0);
        if (o instanceof Rad r) {
            r.beschleunigen(4);
            System.out.println(r);
        }
        System.out.println(o.equals(alle.get(0)) + " " + o.hashCode());
    }
}

