import java.util.*;

class Schluessel {
    final String teil;
    final int nummer;
    Schluessel(String teil, int nummer) { this.teil = teil; this.nummer = nummer; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Schluessel)) return false;
        Schluessel s = (Schluessel) o;
        return nummer == s.nummer && teil.equals(s.teil);
    }

    @Override
    public int hashCode() { return Objects.hash(teil, nummer); }

    @Override
    public String toString() { return teil + "#" + nummer; }
}

public class Main {
    public static void main(String[] args) {
        Set<Schluessel> s = new HashSet<>();
        s.add(new Schluessel("a", 1));
        s.add(new Schluessel("a", 1));
        s.add(new Schluessel("b", 2));
        s.add(new Schluessel("zz", 99));
        System.out.println(s.size() + " " + s);
        System.out.println(s.contains(new Schluessel("b", 2)));
        System.out.println("Ab".hashCode() + " " + Objects.hash(1, 2) + " " + Objects.equals(null, null));
        System.out.println(Objects.hash("x", 2.5, true, 'c', 7L));
        Set<String> staedte = new HashSet<>(List.of("Rom", "Paris", "Berlin", "Wien", "Oslo", "Madrid", "Prag", "Bern"));
        System.out.println(staedte);
        Set<Double> d = new HashSet<>();
        d.add(1.5); d.add(-2.0); d.add(100.25); d.add(0.1);
        System.out.println(d);
        Set<Integer> zahlen = new HashSet<>();
        for (int i = 0; i < 40; i += 3) zahlen.add(i * 37 % 101);
        System.out.println(zahlen);
        Map<Boolean, String> wahr = new HashMap<>();
        wahr.put(true, "ja");
        wahr.put(false, "nein");
        System.out.println(wahr);
        Map<String, Integer> m = new HashMap<>();
        String[] woerter = {"Apfel", "Birne", "Kiwi", "Mango", "Zitrone", "Ananas", "Banane", "Dattel", "Feige", "Guave", "Litschi", "Melone", "Orange"};
        for (String w : woerter) m.put(w, w.length());
        System.out.println(m);
        m.remove("Kiwi");
        m.put("Kiwi", 0);
        System.out.println(m.keySet());
        Map<Long, Integer> lang = new HashMap<>();
        lang.put(5000000000L, 1);
        lang.put(3L, 2);
        System.out.println(lang);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

interface Form {
    double PI_UNGEFAEHR = 3.14;
    double flaeche();
    default String beschreibung() {
        return "Form mit Fläche " + flaeche();
    }
    static Form einheit() {
        return new Quadrat(1);
    }
}

interface Benannt {
    String name();
}

class Quadrat implements Form, Benannt, Comparable<Quadrat> {
    private final double seite;
    Quadrat(double seite) { this.seite = seite; }
    public double flaeche() { return seite * seite; }
    public String name() { return "Quadrat " + seite; }
    public int compareTo(Quadrat other) { return Double.compare(seite, other.seite); }
    public String toString() { return name(); }
}

class Kreis implements Form {
    private final double r;
    Kreis(double r) { this.r = r; }
    public double flaeche() { return PI_UNGEFAEHR * r * r; }
    @Override
    public String beschreibung() { return "Kreis mit Radius " + r; }
}

class Box<T> {
    private T inhalt;
    void lege(T x) { inhalt = x; }
    T hole() { return inhalt; }
    boolean istLeer() { return inhalt == null; }
}

public class Main {
    static <T> void zeige(T wert) {
        System.out.println("Wert: " + wert);
    }

    static double gesamt(List<Form> formen) {
        double summe = 0;
        for (Form f : formen) summe += f.flaeche();
        return summe;
    }

    public static void main(String[] args) {
        List<Form> formen = new ArrayList<>();
        formen.add(new Quadrat(2));
        formen.add(new Kreis(1));
        formen.add(Form.einheit());
        for (Form f : formen) {
            System.out.println(f.beschreibung());
        }
        System.out.println(gesamt(formen));
        Benannt b = new Quadrat(3);
        System.out.println(b.name());
        List<Quadrat> qs = new ArrayList<>(List.of(new Quadrat(5), new Quadrat(1.5), new Quadrat(3)));
        Collections.sort(qs);
        System.out.println(qs);
        System.out.println(Collections.max(qs));
        Box<String> box = new Box<>();
        System.out.println(box.istLeer());
        box.lege("Apfel");
        System.out.println(box.hole().toUpperCase());
        Box<Integer> zahlBox = new Box<>();
        zahlBox.lege(41);
        int x = zahlBox.hole() + 1;
        System.out.println(x);
        zeige(3.5);
        zeige("Hi");
        zeige(new Quadrat(4));
        System.out.println(Form.PI_UNGEFAEHR);
    }
}

class Konto {
    private static int anzahl = 0;
    private final String inhaber;
    private double stand;
    int[] buchungen = new int[3];
    String notiz;

    Konto(String inhaber) {
        this(inhaber, 0);
    }

    Konto(String inhaber, double start) {
        this.inhaber = inhaber;
        this.stand = start;
        anzahl++;
    }

    void einzahlen(double betrag) {
        if (betrag <= 0) {
            System.out.println("Ungültig: " + betrag);
            return;
        }
        stand += betrag;
    }

    void einzahlen(int betrag, int mal) {
        for (int i = 0; i < mal; i++) {
            einzahlen(betrag);
        }
    }

    double getStand() { return stand; }
    String getInhaber() { return inhaber; }
    static int getAnzahl() { return anzahl; }

    @Override
    public String toString() {
        return inhaber + ": " + stand + " €";
    }
}

public class Main {
    static int zaehler;

    static void verdopple(Konto k) {
        k.einzahlen(k.getStand());
    }

    public static void main(String[] args) {
        Konto a = new Konto("Ada");
        Konto b = new Konto("Bob", 10.5);
        a.einzahlen(20);
        a.einzahlen(-3);
        b.einzahlen(5, 3);
        System.out.println(a);
        System.out.println(b);
        System.out.println("Konten: " + Konto.getAnzahl());
        Konto c = a;
        c.einzahlen(1);
        System.out.println(a.getStand() + " " + (a == c) + " " + (a == b));
        verdopple(b);
        System.out.println(b.getStand());
        System.out.println(a.notiz + " " + a.buchungen.length + " " + a.buchungen[1]);
        Konto[] alle = new Konto[3];
        alle[0] = a;
        alle[2] = b;
        for (Konto k : alle) {
            if (k != null) {
                System.out.println("- " + k.getInhaber());
            } else {
                System.out.println("- leer");
            }
        }
        zaehler += 2;
        System.out.println(zaehler + " " + Main.zaehler);
        String text = "Konto " + b;
        System.out.println(text);
        System.out.println(String.valueOf(a).length());
        System.out.printf("%s hat %.2f%n", a.getInhaber(), a.getStand());
        System.out.printf("[%s]%n", b);
    }
}

abstract class Tier {
    protected String name;
    private int beine;

    Tier(String name, int beine) {
        this.name = name;
        this.beine = beine;
    }

    abstract String laut();

    String vorstellen() {
        return name + " (" + beine + " Beine) sagt " + laut();
    }

    int getBeine() { return beine; }
}

class Hund extends Tier {
    Hund(String name) {
        super(name, 4);
    }

    @Override
    String laut() { return "Wuff"; }

    void apportieren() {
        System.out.println(name + " holt den Ball");
    }
}

class Welpe extends Hund {
    Welpe(String name) {
        super(name);
    }

    @Override
    String laut() { return "Wiff (" + super.laut() + ")"; }

    @Override
    String vorstellen() {
        return "Klein: " + super.vorstellen();
    }
}

class Vogel extends Tier {
    Vogel(String name) { super(name, 2); }
    String laut() { return "Piep"; }
}

public class Main {
    public static void main(String[] args) {
        Tier[] tiere = { new Hund("Rex"), new Vogel("Tweety"), new Welpe("Fips") };
        for (Tier t : tiere) {
            System.out.println(t.vorstellen());
        }
        int summe = 0;
        for (Tier t : tiere) {
            summe += t.getBeine();
            if (t instanceof Hund h) {
                h.apportieren();
            }
            System.out.println(t.getClass().getSimpleName() + " " + (t instanceof Hund) + " " + (t instanceof Welpe));
        }
        System.out.println("Beine: " + summe);
        Tier t = tiere[2];
        Hund h = (Hund) t;
        System.out.println(h.laut());
        Object o = h;
        System.out.println(o instanceof Tier);
        System.out.println(o.getClass().getName());
        try {
            Vogel v = (Vogel) t;
            System.out.println(v.laut());
        } catch (ClassCastException e) {
            System.out.println("Kein Vogel");
        }
        Object nichts = null;
        System.out.println(nichts instanceof Tier);
    }
}

